def safe_execute(
    *,
    fallback: Any,
    message: str = "Operation failed",
    log_level: str = "warning",
    silent_exceptions: tuple[type[BaseException], ...] = (),
) -> Callable[[F], F]:
    """Decorator factory that swallows exceptions and returns a fallback.

    When the wrapped function succeeds, its return value is returned
    unchanged. When it raises, the ``fallback`` value is returned instead.

    Args:
        fallback: The value to return when the wrapped function raises.
        message: The message to log when an exception is caught. If falsy,
            no logging is performed.
        log_level: The ``LOGGER`` method to call (e.g. ``"debug"``,
            ``"warning"``, ``"error"``).
        silent_exceptions: Exception types that are swallowed without any
            logging.
    """

    def decorator(func: F) -> F:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                return func(*args, **kwargs)
            except silent_exceptions:
                return fallback
            except Exception:
                if message:
                    getattr(LOGGER, log_level)(message, exc_info=True)
                return fallback

        return wrapper  # type: ignore[return-value]

    return decorator


